// A C++98-style resource-managing class adhering to the Rule of Three.
class LegacyString {
public:
    LegacyString(const char* value = "") {
        // Allocate resource
        data_ = new char[strlen(value) + 1];
        strcpy(data_, value);
    }

    // 1. Destructor: Releases the resource.
    ~LegacyString() {
        delete[] data_;
    }

    // 2. Copy Constructor: Performs a deep copy.
    LegacyString(const LegacyString& other) {
        data_ = new char[strlen(other.data_) + 1];
        strcpy(data_, other.data_);
    }

    // 3. Copy Assignment Operator: Handles self-assignment and performs a deep copy.
    LegacyString& operator=(const LegacyString& other) {
        if (this != &other) {
            delete[] data_; // Release old resource
            data_ = new char[strlen(other.data_) + 1];
            strcpy(data_, other.data_);
        }
        return *this;
    }
private:
    char* data_;
};
